import 'dart:convert';import '../preference_sync/preference_protocol.dart' show PreferenceScope;
class WorkFailure implements Exception {final String code;final int status;const WorkFailure(this.code,[this.status=0]);}
String recordSuffix(String id){if(!RegExp(r'^[A-Za-z0-9._:-]{1,80}$').hasMatch(id))throw const WorkFailure('invalid');return utf8.encode(id).map((b)=>b.toRadixString(16).padLeft(2,'0')).join();}
bool validWorkDate(String value){if(!RegExp(r'^\d{4}-\d{2}-\d{2}$').hasMatch(value)||value.startsWith('0000'))return false;final d=DateTime.tryParse('${value}T00:00:00Z');return d!=null&&d.toIso8601String().substring(0,10)==value;}
List<({String date,int day,bool inMonth})> workMonth(int year,int month,[int firstWeekday=0]){if(year<1900||year>2200||month<1||month>12||firstWeekday<0||firstWeekday>6)throw const WorkFailure('invalid');final first=DateTime.utc(year,month),start=first.subtract(Duration(days:((first.weekday%7)-firstWeekday+7)%7));return List.generate(42,(i){final d=start.add(Duration(days:i));return(date:d.toIso8601String().substring(0,10),day:d.day,inMonth:d.month==month);});}
Map<String,Object?> object(Object? raw,List<String> keys){if(raw is! Map||raw.length!=keys.length||keys.any((k)=>!raw.containsKey(k))||raw.keys.any((k)=>k is! String))throw const WorkFailure('invalid');return Map<String,Object?>.from(raw);}
String _text(Object? raw,int max,[bool empty=false]){if(raw is! String||raw.length>max||!empty&&raw.trim().isEmpty||RegExp(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]').hasMatch(raw))throw const WorkFailure('invalid');return raw;}
class WorkAction {final String id,label,target;final List<String> fields;WorkAction(this.id,this.label,List<String> fields,this.target):fields=List.unmodifiable(fields);Map<String,Object?> toJson()=>{'id':id,'label':label,'fields':fields,'target':target};}
class WorkItem {final String id,title,body,date,lane,meta;final int version;final List<WorkAction> actions;WorkItem({required this.id,required this.version,required this.title,required this.body,required this.date,required this.lane,required this.meta,required List<WorkAction> actions}):actions=List.unmodifiable(actions);Map<String,Object?> toJson()=>{'id':id,'version':version,'title':title,'body':body,'date':date,'lane':lane,'meta':meta,'actions':actions.map((a)=>a.toJson()).toList()};}
class WorkSnapshot {final PreferenceScope scope;final String module;final List<WorkItem> items;final List<({String id,String label})> lanes;final int offset,total;final bool partial;WorkSnapshot._(this.scope,this.module,this.items,this.lanes,this.offset,this.total,this.partial);
 factory WorkSnapshot.fromJson(Object? raw,PreferenceScope expectedScope,String module){final v=object(raw,['scope','module','items','lanes','offset','total','partial']),scope=PreferenceScope.fromJson(v['scope']);if(!scope.same(expectedScope)||v['module']!=module)throw const WorkFailure('denied',403);if(v['items'] is! List||(v['items'] as List).length>1000||v['lanes'] is! List||(v['lanes'] as List).length>20||v['offset'] is! int||(v['offset'] as int)<0||v['total'] is! int||(v['total'] as int)<0||v['partial'] is! bool)throw const WorkFailure('invalid');final lanes=(v['lanes'] as List).map((raw){final l=object(raw,['id','label']),id=_text(l['id'],80);recordSuffix(id);return(id:id,label:_text(l['label'],200));}).toList();if(lanes.map((l)=>l.id).toSet().length!=lanes.length)throw const WorkFailure('invalid');final items=(v['items'] as List).map((raw){final r=object(raw,['id','version','title','body','date','lane','meta','actions']),id=_text(r['id'],80),date=_text(r['date'],10,true),lane=_text(r['lane'],80,true);recordSuffix(id);if(r['version'] is! int||(r['version'] as int)<1||r['actions'] is! List||(r['actions'] as List).length>20||date.isNotEmpty&&!validWorkDate(date)||lane.isNotEmpty&&!lanes.any((l)=>l.id==lane))throw const WorkFailure('invalid');final actions=(r['actions'] as List).map((raw){final a=object(raw,['id','label','fields','target']),id=_text(a['id'],80),target=_text(a['target'],80,true);recordSuffix(id);if(a['fields'] is! List||(a['fields'] as List).any((f)=>!['title','body','date'].contains(f))||(a['fields'] as List).toSet().length!=(a['fields'] as List).length||target.isNotEmpty&&!lanes.any((l)=>l.id==target))throw const WorkFailure('invalid');return WorkAction(id,_text(a['label'],200),List<String>.from(a['fields'] as List),target);}).toList();if(actions.map((a)=>a.id).toSet().length!=actions.length)throw const WorkFailure('invalid');return WorkItem(id:id,version:r['version'] as int,title:_text(r['title'],500),body:_text(r['body'],5000,true),date:date,lane:lane,meta:_text(r['meta'],1000,true),actions:actions);}).toList();if(items.map((i)=>i.id).toSet().length!=items.length||(v['total'] as int)<items.length)throw const WorkFailure('invalid');return WorkSnapshot._(scope,module,List.unmodifiable(items),List.unmodifiable(lanes),v['offset'] as int,v['total'] as int,v['partial'] as bool);}
 Map<String,Object?> toJson()=>{'scope':scope.toJson(),'module':module,'items':items.map((i)=>i.toJson()).toList(),'lanes':lanes.map((l)=>{'id':l.id,'label':l.label}).toList(),'offset':offset,'total':total,'partial':partial};}
class WorkCommand {final String itemId,action;final int version;final Map<String,String> fields;WorkCommand(this.itemId,this.version,this.action,Map<String,String> fields):fields=Map.unmodifiable(fields);Map<String,Object?> toJson()=>{'itemId':itemId,'version':version,'action':action,'fields':fields};}
WorkCommand validateWorkCommand(WorkItem item,String actionId,Map<String,String> fields){final actions=item.actions.where((a)=>a.id==actionId).toList();if(actions.length!=1)throw const WorkFailure('denied',403);final action=actions.single;if(fields.keys.any((k)=>!action.fields.contains(k))||action.fields.any((k)=>!fields.containsKey(k)))throw const WorkFailure('invalid',400);for(final e in fields.entries){_text(e.value,e.key=='body'?5000:500,true);if(e.key=='date'&&!validWorkDate(e.value))throw const WorkFailure('invalid',400);}return WorkCommand(item.id,item.version,actionId,fields);}
